        }

        .card:hover {
            box-shadow: var(--shadow-hover);
        }

        .card-header {
            background-color: #f8fafc;
            padding: 16px 24px;
            border-bottom: 1px solid var(--border);
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .card-icon {
            width: 24px;
            height: 24px;
            background-color: var(--primary);
            color: white;
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            font-size: 14px;
        }

        .card-title {
            font-weight: 600;
            color: var(--secondary);
            font-size: 1.1rem;
        }

        .card-body {
            padding: 24px;
        }

        /* Typography inside cards */
        .card-body p {
